app/globals.css:
@import "tailwindcss";

:root{
  --paper:#eee7dc;
  --muted:#938a7e;
  --bronze:#b18a59;
  --line:rgba(236,229,216,.16);
  --black:#090a08;
}
*{box-sizing:border-box}
html,body{margin:0;background:var(--black);color:var(--paper);font-family:Arial,Helvetica,sans-serif}
body{overflow-x:hidden}
a{color:inherit;text-decoration:none}
button{font:inherit}
.canvas-shell{position:fixed;inset:0;height:100svh;z-index:0}
.scroll-track{position:relative;z-index:1;pointer-events:none}
.scroll-act{height:150vh}
.scroll-act:first-child{height:125vh}
.scroll-act:last-child{height:125vh}

.topbar{
  position:fixed;top:0;left:0;right:0;z-index:20;height:70px;
  display:grid;grid-template-columns:1fr auto 1fr;align-items:center;
  padding:0 clamp(20px,4vw,56px);
  border-bottom:1px solid var(--line);
  background:linear-gradient(180deg,rgba(5,6,5,.58),rgba(5,6,5,0));
  backdrop-filter:blur(3px);
  font:500 10px/1 ui-monospace,SFMono-Regular,Menlo,monospace;
  letter-spacing:.13em;
}
.brand{display:flex;gap:13px;align-items:center}
.brand span{
  display:grid;place-items:center;width:30px;height:30px;border:1px solid rgba(255,255,255,.25);
  color:#e9dac5;font-weight:700
}
.brand b{font-weight:500;color:#a69e92}
.year{color:#c9b493}
.topbar nav{justify-self:end;display:flex;gap:22px;color:#9a9389}
.topbar nav a{position:relative}
.topbar nav a:after{
  content:"";position:absolute;left:0;right:0;bottom:-6px;height:1px;background:#c9ae86;
  transform:scaleX(.15);transform-origin:left;opacity:.4;transition:.3s ease
}
.topbar nav a:hover:after{transform:scaleX(1);opacity:1}

.story-copy{
  position:fixed;left:clamp(24px,6vw,96px);bottom:clamp(70px,11vh,132px);z-index:12;
  width:min(660px,calc(100vw - 48px));pointer-events:none;
}
.story-copy>p:first-child{
  margin:0 0 14px;color:#b6976d;font:600 10px/1 ui-monospace,SFMono-Regular,monospace;letter-spacing:.18em
}
.story-copy h1{
  margin:0;font-weight:300;font-size:clamp(3.5rem,7.2vw,8.2rem);letter-spacing:-.075em;line-height:.86;
  max-width:780px;text-wrap:balance
}
.story-copy h2{
  margin:18px 0 0;color:#c5beb3;font-weight:400;font-size:clamp(.9rem,1.35vw,1.16rem);
  line-height:1.45;max-width:650px
}
.story-copy .rule{width:82px;height:1px;background:#9f815c;margin:21px 0 18px}
.story-copy .body{margin:0;color:#827c73;font-size:12px;line-height:1.7;max-width:510px}

.rail{
  position:fixed;z-index:11;right:clamp(18px,3vw,42px);top:50%;transform:translateY(-50%);
  display:grid;gap:13px;font:500 8px/1 ui-monospace,SFMono-Regular,monospace;letter-spacing:.08em;color:#65625c;
  pointer-events:none
}
.rail span{display:grid;grid-template-columns:16px auto;gap:8px;align-items:center;transition:.35s ease}
.rail i{display:block;width:5px;height:1px;background:#69665f;transition:.35s ease}
.rail .active{color:#c7b08e}
.rail .active i{width:16px;background:#c79b62;box-shadow:0 0 12px rgba(199,155,98,.45)}
.hint{
  position:fixed;z-index:12;bottom:22px;left:50%;transform:translateX(-50%);white-space:nowrap;
  color:#756f65;font:500 8px/1 ui-monospace,SFMono-Regular,monospace;letter-spacing:.16em;pointer-events:none
}

.inspector{
  position:fixed;inset:0;z-index:80;display:grid;place-items:center;padding:24px;
  background:rgba(5,6,5,.72);backdrop-filter:blur(15px)
}
.inspector-panel{
  position:relative;width:min(820px,100%);min-height:min(570px,76vh);padding:90px clamp(28px,7vw,76px) 48px;
  border:1px solid rgba(255,255,255,.15);
  background:
    radial-gradient(circle at 78% 8%,rgba(180,137,81,.13),transparent 31%),
    linear-gradient(145deg,#151713,#0c0d0b);
  box-shadow:0 40px 140px rgba(0,0,0,.6)
}
.inspector-panel button{
  position:absolute;top:25px;left:26px;border:0;background:none;color:#9b9286;cursor:pointer;
  font:600 9px/1 ui-monospace,monospace;letter-spacing:.12em
}
.inspector-panel>p:first-of-type{color:#ae8f68;font:600 10px/1 ui-monospace,monospace;letter-spacing:.16em}
.inspector-panel h3{
  margin:18px 0 20px;font-weight:300;font-size:clamp(3rem,7vw,6.4rem);letter-spacing:-.06em;line-height:.9
}
.inspector-panel>p:last-child{color:#918a80;line-height:1.75;max-width:600px}

@media(max-width:760px){
  .topbar{grid-template-columns:1fr auto;padding:0 18px;height:60px}
  .year{display:none}
  .brand b{display:none}
  .topbar nav{gap:13px}
  .story-copy{left:22px;bottom:70px}
  .story-copy h1{font-size:clamp(3.2rem,17vw,6rem)}
  .story-copy .body{font-size:11px;max-width:330px}
  .rail{display:none}
  .hint{bottom:14px}
}
@media(prefers-reduced-motion:reduce){
  .story-copy,.topbar nav a:after{transition:none!important}
}
.repo-link{
  display:inline-block;margin-top:30px;padding-bottom:6px;border-bottom:1px solid rgba(199,174,134,.55);
  color:#cdb99a;font:600 10px/1 ui-monospace,monospace;letter-spacing:.12em;pointer-events:auto
}
